function saveGlossaryEntry(){const name=$('glossaryEntryName').value.trim();if(!name){$('glossaryEntryName').focus();return}const entry={id:editingGlossaryId||'glossary-'+Date.now(),kind:$('glossaryEntryKind').value,name,fandom:$('glossaryEntryFandom').value.trim(),category:$('glossaryEntryCategory').value.trim(),aliases:splitList($('glossaryEntryAliases').value),notes:$('glossaryEntryNotes').value.trim()};const ix=glossaryEntries.findIndex(x=>x.id===entry.id);if(ix>=0)glossaryEntries[ix]=entry;else glossaryEntries.unshift(entry);localStorage.setItem('sciGlossary',JSON.stringify(glossaryEntries));if(entry.kind==='fandom')rememberFandomName(entry.name);$('glossaryEntryForm').hidden=true;renderGlossary()}
