let notePages=loadArray('sciNotes',[]),currentNoteId=null,lastNoteEditor=null;
function saveNotePages(){localStorage.setItem('sciNotes',JSON.stringify(notePages))}
function currentNote(){return notePages.find(n=>n.id===currentNoteId)||null}
function noteChildren(parentId){return notePages.filter(n=>(n.parentId||'')===(parentId||''))}
function createNotePage(parentId=null){const title=prompt(t('عنوان الصفحة الجديدة:','New page title:'),t('صفحة جديدة','New page'));if(title===null)return;const page={id:'note-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),parentId:parentId||'',title:title.trim()||t('بدون عنوان','Untitled'),icon:'✦',banner:'',blocks:[],order:Date.now()};notePages.push(page);saveNotePages();navigateToNotes(page.id)}
function navigateToNotes(id=null){if(activeFandom)save();activeFandom=null;localStorage.removeItem('sciActiveFandomId');setMainPage('notes');$('atlasNav').hidden=true;$('fandomView').hidden=true;$('atlasView').hidden=true;$('shipsView').hidden=true;$('glossaryView').hidden=true;$('notesView').hidden=false;const hashId=location.hash.match(/^#note\/(.+)$/)?.[1];currentNoteId=notePages.some(n=>n.id===id)?id:(notePages.some(n=>n.id===hashId)?hashId:(notePages[0]?.id||null));if(currentNoteId){localStorage.setItem('sciActiveNoteId',currentNoteId);history.replaceState(null,'',`#note/${encodeURIComponent(currentNoteId)}`)}else localStorage.removeItem('sciActiveNoteId');renderNotes();updateTop()}
function renderNotesTree(){const host=$('notesTree');const draw=(parentId='',depth=0)=>noteChildren(parentId).sort((a,b)=>(a.order||0)-(b.order||0)).map(p=>`<button class="notes-tree-item ${p.id===currentNoteId?'active':''}" style="padding-inline-start:${9+depth*15}px" data-note="${esc(p.id)}"><span class="tree-icon">${esc(p.icon||'✦')}</span><span>${esc(p.title||t('بدون عنوان','Untitled'))}</span></button>${draw(p.id,depth+1)}`).join('');host.innerHTML=draw();host.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>navigateToNotes(b.dataset.note))}
function safeDocUrl(value){try{const u=new URL(String(value||''),location.href);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
function cleanNoteHtml(html){const template=document.createElement('template');template.innerHTML=String(html||'');template.content.querySelectorAll('script,style,iframe,object,embed,form').forEach(n=>n.remove());template.content.querySelectorAll('*').forEach(el=>{if(!['B','STRONG','I','EM','U','S','STRIKE','UL','OL','LI','A','SPAN','BR','P','SUB','SUP','FONT','MARK','DEL','CODE','PRE','TABLE','THEAD','TBODY','TFOOT','TR','TH','TD','CAPTION','COLGROUP','COL','IMG','FIGURE'].includes(el.tagName)){el.replaceWith(...el.childNodes);return}[...el.attributes].forEach(a=>{if(a.name.startsWith('on')||!['href','target','rel','style','color','data-open-note','src','alt','width'].includes(a.name))el.removeAttribute(a.name)});if(el.hasAttribute('src')){const src=el.getAttribute('src');if(!/^data:image\/(png|jpe?g|gif|webp|avif);base64,[a-z0-9+/=]+$/i.test(src)&&!/^https:\/\//i.test(src))el.removeAttribute('src')}if(el.hasAttribute('color')&&!/^(#[0-9a-f]{3,8}|rgb\([0-9, %]+\))$/i.test(el.getAttribute('color')))el.removeAttribute('color');if(el.hasAttribute('href')){if(el.hasAttribute('data-open-note')){}else{const u=safeDocUrl(el.getAttribute('href'));if(u){el.setAttribute('href',u);el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer')}else el.removeAttribute('href')}}if(el.hasAttribute('style')){const allowed={color:/^(#[0-9a-f]{3,8}|rgb\([0-9, %]+\))$/i,'background-color':/^(#[0-9a-f]{3,8}|rgb\([0-9, %]+\))$/i,'text-align':/^(left|right|center|justify)$/i,'font-weight':/^(normal|bold|[1-9]00)$/i,'font-style':/^(normal|italic|oblique)$/i,'text-decoration':/^(none|underline|line-through|underline line-through)$/i,'white-space':/^(normal|pre|pre-wrap|pre-line)$/i,'width':/^([0-9.]+%|[0-9.]+px)$/i,'max-width':/^([0-9.]+%|[0-9.]+px)$/i,'height':/^([0-9.]+%|[0-9.]+px)$/i};const safe=el.getAttribute('style').split(';').map(x=>x.split(':')).filter(x=>x.length>=2).map(([k,...v])=>[k.trim().toLowerCase(),v.join(':').trim()]).filter(([k,v])=>allowed[k]?.test(v)).map(([k,v])=>`${k}:${v}`).join(';');if(safe)el.setAttribute('style',safe);else el.removeAttribute('style')}});return template.innerHTML}
function renderNoteBlock(block){const id=esc(block.id),type=block.type||'paragraph';if(type==='divider')return `<div class="note-block" data-id="${id}" data-type="divider"><button class="note-block-delete" data-remove="${id}" aria-label="Delete block">×</button></div>`;if(type==='image'){const url=/^data:image\/(png|jpe?g|gif|webp|avif);base64,[a-z0-9+/=]+$/i.test(block.url||'')?block.url:safeDocUrl(block.url);return `<div class="note-block" data-id="${id}" data-type="image"><button class="note-block-delete" data-remove="${id}" aria-label="Delete block">×</button>${url?`<img class="note-block-image" src="${esc(url)}" alt="${esc(block.text||'Document image')}">`:block.missing?`<div class="note-image-missing">Image missing from Notion ZIP: <b>${esc(block.text||'unknown file')}</b>. Re-export with files or attach it using Set image URL.</div>`:''}<button data-edit-url="${id}">${url?'Set image URL':'Attach image URL'}</button></div>`}if(type==='playlist'){const url=safeDocUrl(block.url);let embed='';try{const u=new URL(url);if(u.hostname==='open.spotify.com'&&u.pathname.includes('/playlist/'))embed=`https://open.spotify.com/embed/playlist/${encodeURIComponent(u.pathname.split('/playlist/')[1].split('/')[0])}`;else if((u.hostname==='youtube.com'||u.hostname==='www.youtube.com'||u.hostname==='youtu.be')&&u.searchParams.get('list'))embed=`https://www.youtube-nocookie.com/embed/videoseries?list=${encodeURIComponent(u.searchParams.get('list'))}`}catch{}return `<div class="note-block" data-id="${id}" data-type="playlist"><button class="note-block-delete" data-remove="${id}" aria-label="Delete block">×</button>${embed?`<div class="note-playlist"><iframe src="${esc(embed)}" title="Playlist" loading="lazy" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" allowfullscreen></iframe></div>`:`<button data-edit-url="${id}">Add Spotify or YouTube playlist URL</button>`}</div>`}if(type==='pageLink'){const target=notePages.find(n=>n.id===block.targetId);return `<div class="note-block" data-id="${id}" data-type="pageLink"><button class="note-block-delete" data-remove="${id}" aria-label="Delete block">×</button>${target?`<a class="note-page-link" href="#note/${encodeURIComponent(target.id)}" data-open-note="${esc(target.id)}">${esc(target.icon||'✦')} ${esc(block.text||target.title)}</a>`:`<label class="note-page-link">Choose page <select data-select-target="${id}"><option value="">Select a page</option>${notePages.filter(n=>n.id!==currentNoteId).map(n=>`<option value="${esc(n.id)}">${esc(n.title)}</option>`).join('')}</select></label>`}</div>`}if(type==='toggle'){return `<div class="note-block" data-id="${id}" data-type="toggle"><button class="note-block-delete" data-remove="${id}" aria-label="Delete block">×</button><button class="note-toggle" data-toggle="${id}">${block.collapsed?'▸':'▾'} ${block.titleHtml?cleanNoteHtml(block.titleHtml):esc(block.text||'Toggle heading')}</button><div class="note-toggle-body" ${block.collapsed?'hidden':''} contenteditable="true" data-edit="${id}" data-field="body">${cleanNoteHtml(block.body||'Click to add toggle content')}</div></div>`}const editable=['heading1','heading2','heading3','paragraph','quote','callout','rich'].includes(type);return `<div class="note-block" data-id="${id}" data-type="${esc(type)}">${editable?`<div class="note-content" contenteditable="true" data-edit="${id}" data-field="html" data-placeholder="${type==='paragraph'?'Type something…':''}">${cleanNoteHtml(block.html||'')}</div>`:''}<button class="note-block-delete" data-remove="${id}" aria-label="Delete block">×</button></div>`}
function renderNotes(){renderNotesTree();const page=currentNote();$('noteEmpty').hidden=Boolean(page);$('noteTitle').disabled=!page;$('noteBlocks').innerHTML='';$('noteSubpages').innerHTML='';$('noteBreadcrumb').textContent='';$('noteBanner').style.backgroundImage='';$('noteBanner').hidden=true;$('noteBanner').textContent='';$('noteIconButton').disabled=!page;$('noteBannerButton').disabled=!page;$('noteLinkButton').disabled=!page;$('noteDeleteButton').disabled=!page;if(!page){$('noteTitle').value='';$('noteBlocks').innerHTML='';$('noteEmpty').textContent=t('لا توجد مستندات بعد. اختاري “New page” لإنشاء أول صفحة.','No documents yet. Choose “New page” to create your first page.');$('noteSubpages').innerHTML='';return}$('noteEmpty').hidden=true;$('noteTitle').value=page.title||'';$('noteIconButton').textContent=page.icon||'✦';if(safeDocUrl(page.banner)){$('noteBanner').hidden=false;$('noteBanner').style.backgroundImage=`url("${safeDocUrl(page.banner)}")`;}const crumbs=[];let cursor=page;while(cursor){crumbs.unshift(cursor.title||'Untitled');cursor=notePages.find(n=>n.id===cursor.parentId)}$('noteBreadcrumb').textContent=crumbs.join(' / ');$('noteBlocks').innerHTML=(page.blocks||[]).map(renderNoteBlock).join('');const children=noteChildren(page.id);$('noteSubpages').innerHTML=children.map(n=>`<button data-open-note="${esc(n.id)}">${esc(n.icon||'✦')}　${esc(n.title||'Untitled')}　›</button>`).join('');$('noteSubpages').querySelectorAll('[data-open-note]').forEach(b=>b.onclick=()=>navigateToNotes(b.dataset.openNote));$('noteBlocks').querySelectorAll('[data-open-note]').forEach(b=>b.onclick=e=>{e.preventDefault();navigateToNotes(b.dataset.openNote)});$('noteBlocks').querySelectorAll('[data-edit-url]').forEach(b=>b.onclick=()=>{const block=page.blocks.find(x=>x.id===b.dataset.editUrl),url=prompt(block.type==='image'?'Image URL:':'Spotify playlist or YouTube playlist URL:',block.url||'');if(url!==null){block.url=url.trim();saveNotePages();renderNotes()}});$('noteBlocks').querySelectorAll('[data-select-target]').forEach(select=>select.onchange=()=>{const block=page.blocks.find(x=>x.id===select.dataset.selectTarget),target=notePages.find(n=>n.id===select.value);if(block&&target){block.targetId=target.id;block.text=target.title;saveNotePages();renderNotes()}});$('noteBlocks').querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const block=page.blocks.find(x=>x.id===b.dataset.toggle);block.collapsed=!block.collapsed;saveNotePages();renderNotes()});$('noteBlocks').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{page.blocks=page.blocks.filter(x=>x.id!==b.dataset.remove);saveNotePages();renderNotes()})}
function addNoteBlock(type){const page=currentNote();if(!page){alert(t('أنشئي صفحة أولًا.','Create a page first.'));return}let block={id:'block-'+Date.now()+'-'+Math.random().toString(36).slice(2,5),type,html:'',text:'',body:'',url:'',targetId:''};if(type==='image'){$('noteImageFile').click();return}if(type==='divider'){}if(type==='playlist'){block.url=prompt(type==='playlist'?'Spotify or YouTube playlist URL:':'URL:','')||''}if(type==='pageLink'){const choices=notePages.filter(n=>n.id!==page.id);const name=prompt('Type the target page title:\n'+choices.map(n=>n.title).join('\n'));const target=choices.find(n=>n.title.toLowerCase()===String(name||'').toLowerCase());block.targetId=target?.id||'';block.text=target?.title||''}if(type==='toggle'){block.text=prompt('Toggle heading:','Click to expand')||'Toggle heading';block.body='Click to add toggle content'}page.blocks=page.blocks||[];page.blocks.push(block);saveNotePages();renderNotes();const node=$(`noteBlocks`).querySelector(`[data-id="${CSS.escape(block.id)}"] [contenteditable=true]`)||$(`noteBlocks`).querySelector(`[data-id="${CSS.escape(block.id)}"][contenteditable=true]`);if(node){node.focus();const range=document.createRange();range.selectNodeContents(node);range.collapse(false);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);lastNoteEditor=node}}
function onNoteBlockInput(e){const editor=e.target.closest('[data-edit]');if(!editor)return;lastNoteEditor=editor;const page=currentNote(),block=page?.blocks.find(x=>x.id===editor.dataset.edit);if(!block)return;if(editor.dataset.field==='body')block.body=cleanNoteHtml(editor.innerHTML);else block.html=cleanNoteHtml(editor.innerHTML);saveNotePages()}
function saveFocusedBlock(){if(lastNoteEditor)lastNoteEditor.dispatchEvent(new Event('input',{bubbles:true}))}
function onNoteBlockClick(e){const b=e.target.closest('[data-remove]');if(b){const p=currentNote();p.blocks=p.blocks.filter(x=>x.id!==b.dataset.remove);saveNotePages();renderNotes()}}
function deleteCurrentNote(){const page=currentNote();if(!page||!confirm(t('حذف الصفحة وكل الصفحات الفرعية التابعة لها؟','Delete this page and all its subpages?')))return;const ids=new Set([page.id]);let changed=true;while(changed){changed=false;for(const n of notePages)if(ids.has(n.parentId)&&!ids.has(n.id)){ids.add(n.id);changed=true}}notePages=notePages.filter(n=>!ids.has(n.id));currentNoteId=notePages.find(n=>!n.parentId)?.id||null;saveNotePages();navigateToNotes(currentNoteId)}

async function loadJSZip(){if(window.JSZip)return window.JSZip;return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js';script.onload=()=>resolve(window.JSZip);script.onerror=()=>reject(new Error('ZIP reader could not load'));document.head.appendChild(script)})}
function importedRichHtml(element,path,pageMap,assets={}){const clone=element.cloneNode(true);const resolve=target=>{try{return decodeURIComponent(new URL(target,'https://notion-export.invalid/'+path).pathname).replace(/^\//,'')}catch{return target}};const colors={gray:'rgba(125,122,117,1)',brown:'rgba(159,118,90,1)',orange:'rgba(210,123,45,1)',yellow:'rgba(203,148,52,1)',teal:'rgba(80,148,110,1)',blue:'rgba(56,125,201,1)',purple:'rgba(154,107,180,1)',pink:'rgba(193,76,138,1)',red:'rgba(207,81,72,1)',gray_background:'rgba(42,28,0,.07)',brown_background:'rgba(139,46,0,.086)',orange_background:'rgba(224,101,1,.129)',yellow_background:'rgba(211,168,0,.137)',teal_background:'rgba(0,100,45,.09)',blue_background:'rgba(0,124,215,.094)',purple_background:'rgba(102,0,178,.078)',pink_background:'rgba(197,0,93,.086)',red_background:'rgba(223,22,0,.094)'};for(const el of [clone,...clone.querySelectorAll('*')]){const cls=[...el.classList];for(const c of cls){if(c.startsWith('highlight-')){const k=c.slice(10);if(colors[k])el.style.setProperty(k.endsWith('_background')?'background-color':'color',colors[k])}if(c.startsWith('block-color-')){const k=c.slice(12);if(colors[k])el.style.setProperty(k.endsWith('_background')?'background-color':'color',colors[k])}}if(el.matches('img')){const src=el.getAttribute('src')||'';const local=resolve(src),data=assets[local]||assets[src];if(data)el.setAttribute('src',data);else if(!/^https?:/i.test(src)){const missing=document.createElement('span');missing.className='notion-image-missing';missing.textContent=`[Image file not included in ZIP: ${src.split('/').pop()}]`;el.replaceWith(missing)}}}for(const a of clone.querySelectorAll('a[href]')){try{const dest=resolve(a.getAttribute('href')),target=pageMap[dest];if(target){a.setAttribute('href',`#note/${encodeURIComponent(target.id)}`);a.setAttribute('data-open-note',target.id)}}catch{}}return cleanNoteHtml(clone.innerHTML)}
function htmlToNoteBlocks(root,pageMap,assets,path){const blocks=[],resolvePath=target=>{try{return decodeURIComponent(new URL(target,'https://notion-export.invalid/'+path).pathname).replace(/^\//,'')}catch{return target}},add=(type,extra={})=>blocks.push({id:'block-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),type,...extra});function walk(node){for(const el of [...node.children]){const tag=el.tagName.toLowerCase(),text=el.textContent.trim(),html=importedRichHtml(el,path,pageMap,assets);if(el.matches('.column-list')){const cols=[...el.querySelectorAll(':scope > .column')];if(cols.length){const cells=cols.map(c=>`<td style="vertical-align:top;width:${Math.round(100/cols.length)}%">${[...c.children].map(x=>importedRichHtml(x,path,pageMap,assets)).join('')}</td>`).join('');add('rich',{html:`<table class="notion-columns"><tbody><tr>${cells}</tr></tbody></table>`});continue}}if(el.matches('.page-cover-image'))continue;if(/^h[1-3]$/.test(tag)){add('heading'+tag[1],{html});continue}if(tag==='hr'){add('divider');continue}if(tag==='img'){const src=el.getAttribute('src')||'',data=assets[resolvePath(src)]||assets[src];add('image',{url:data||'',text:el.getAttribute('alt')||src.split('/').pop(),missing:!data&& !/^https?:/i.test(src)});continue}if(tag==='iframe'||tag==='audio'||tag==='video'){const src=el.getAttribute('src')||el.querySelector('source')?.getAttribute('src')||'';if(src&&/spotify|youtube/i.test(src))add('playlist',{url:safeDocUrl(src)});else if(src)add('rich',{html:`<p><a href="${esc(src)}">${esc(text||src)}</a></p>`});continue}if(tag==='a'&&el.getAttribute('href')?.toLowerCase().endsWith('.html')){const target=pageMap[resolvePath(el.getAttribute('href'))];if(target){add('pageLink',{targetId:target.id,text:target.title});continue}}if(tag==='details'){const summary=el.querySelector('summary'),body=[...el.children].filter(x=>x!==summary).map(x=>importedRichHtml(x,path,pageMap,assets)).join('');add('toggle',{text:summary?.textContent.trim()||'Toggle',titleHtml:summary?importedRichHtml(summary,path,pageMap,assets):'',body,collapsed:!el.open});continue}if(tag==='blockquote'){add('quote',{html});continue}if(tag==='ul'||tag==='ol'||tag==='table'){add('rich',{html});continue}if(tag==='p'){if(text||el.querySelector('img'))add('paragraph',{html});continue}if(tag==='figure'){const img=el.querySelector('img');if(img){walk(img);const cap=el.querySelector('figcaption');if(cap?.textContent.trim())add('paragraph',{html:importedRichHtml(cap,path,pageMap,assets)});continue}}if(['div','section','article','main','header','footer','span'].includes(tag)){if(el.querySelector('img,p,h1,h2,h3,ul,ol,blockquote,table,hr,details,iframe,video,.column-list'))walk(el);else if(text)add('paragraph',{html});continue}if(text)add('paragraph',{html:esc(text)})}}walk(root);return blocks}
function parseExportCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
async function importNotionZip(file){try{const JSZip=await loadJSZip(),zip=await JSZip.loadAsync(file),entries=Object.values(zip.files).filter(f=>!f.dir),htmlFiles=entries.filter(f=>/\.html?$/i.test(f.name)&&!/(^|\/)(index|export|search)\.html?$/i.test(f.name)),csvFiles=entries.filter(f=>/\.csv$/i.test(f.name));if(!htmlFiles.length&&!csvFiles.length)throw new Error('No supported Notion export pages found');const htmlByPath={};for(const f of htmlFiles)htmlByPath[f.name]=await f.async('string');const pageMap={};for(const fileEntry of htmlFiles){const doc=new DOMParser().parseFromString(htmlByPath[fileEntry.name],'text/html'),title=doc.querySelector('.page-title')?.textContent.trim()||doc.querySelector('h1')?.textContent.trim()||doc.title.replace(/\s*\[[^\]]+\]\s*$/,'').trim()||fileEntry.name.split('/').pop().replace(/\.html?$/i,'');pageMap[fileEntry.name]={id:'note-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),title,icon:'✦',banner:'',parentId:'',blocks:[],order:Date.now()}}const assetEntries=entries.filter(f=>!htmlFiles.includes(f)&&!csvFiles.includes(f)),assetLookup=new Map(assetEntries.map(f=>[f.name.toLowerCase(),f])),assets={},missing=new Set();for(const fileEntry of htmlFiles){const doc=new DOMParser().parseFromString(htmlByPath[fileEntry.name],'text/html');for(const img of [...doc.images]){const src=img.getAttribute('src')||'';if(!src||/^https?:/i.test(src))continue;let target;try{const joined=decodeURIComponent(new URL(src,'https://notion-export.invalid/'+fileEntry.name).pathname.replace(/^\//,''));target=assetLookup.get(joined.toLowerCase())||assetLookup.get(decodeURIComponent(src).toLowerCase())||assetEntries.find(f=>f.name.toLowerCase().endsWith('/'+decodeURIComponent(src).split('/').pop().toLowerCase()))}catch{}if(target&&!assets[target.name]){const ext=target.name.split('.').pop().toLowerCase(),mime=({png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp',svg:'image/svg+xml',avif:'image/avif'})[ext]||'application/octet-stream';assets[target.name]=`data:${mime};base64,${await target.async('base64')}`;assets[src]=assets[target.name];try{assets[decodeURIComponent(new URL(src,'https://notion-export.invalid/'+fileEntry.name).pathname).replace(/^\//,'')]=assets[target.name]}catch{}}else if(!target)missing.add(src.split('/').pop())}}const referenced=new Set();for(const f of htmlFiles){const d=new DOMParser().parseFromString(htmlByPath[f.name],'text/html');for(const a of d.querySelectorAll('a[href$=".html"]')){try{const dest=decodeURIComponent(new URL(a.getAttribute('href'),'https://notion-export.invalid/'+f.name).pathname.replace(/^\//,''));if(pageMap[dest])referenced.add(dest)}catch{}}}const rootFile=htmlFiles.find(f=>!referenced.has(f.name))||htmlFiles[0],rootPage=pageMap[rootFile?.name],candidates=htmlFiles.map(f=>pageMap[f.name]);for(const fileEntry of htmlFiles){const page=pageMap[fileEntry.name],doc=new DOMParser().parseFromString(htmlByPath[fileEntry.name],'text/html'),body=doc.querySelector('.page-body')||doc.body;page.blocks=htmlToNoteBlocks(body,pageMap,assets,fileEntry.name);const cover=doc.querySelector('.page-cover-image');if(cover){const src=cover.getAttribute('src')||'';page.banner=assets[src]||assets[decodeURIComponent(src)]||'';if(!page.banner){page.coverMissing=src.split('/').pop();page.blocks.unshift({id:'block-cover-'+Date.now(),type:'callout',html:`<p>Cover image missing from Notion ZIP: <b>${esc(page.coverMissing)}</b>. Re-export with files to include it.</p>`})}}}for(const sourceFile of [rootFile,...htmlFiles.filter(f=>f!==rootFile)]){const sourcePage=pageMap[sourceFile.name],doc=new DOMParser().parseFromString(htmlByPath[sourceFile.name],'text/html');for(const a of doc.querySelectorAll('a[href$=".html"]')){try{const dest=decodeURIComponent(new URL(a.getAttribute('href'),'https://notion-export.invalid/'+sourceFile.name).pathname.replace(/^\//,'')),target=pageMap[dest];if(target&&target.id!==sourcePage.id&&!target.parentId)target.parentId=sourcePage.id}catch{}}}for(const f of htmlFiles){const page=pageMap[f.name];if(page!==rootPage&&!page.parentId)page.parentId=rootPage?.id||''}for(const csvFile of csvFiles){const rows=parseExportCsv(await csvFile.async('string'));if(!rows.length)continue;const headers=rows[0],body=rows.slice(1),name=csvFile.name.split('/').pop().replace(/\s+[0-9a-f]{16,}(?=\.csv$)/i,'').replace(/\.csv$/i,'');const page={id:'note-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),title:name,icon:'▦',banner:'',parentId:rootPage?.id||'',order:Date.now(),blocks:[{id:'block-'+Date.now(),type:'rich',html:`<table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${body.map(r=>`<tr>${headers.map((_,i)=>`<td>${esc(r[i]||'')}</td>`).join('')}</tr>`).join('')}</tbody></table>`}]};candidates.push(page)}notePages=[...notePages,...candidates];saveNotePages();navigateToNotes(rootPage?.id||candidates[0]?.id);const missingText=missing.size?` ${missing.size} image file(s) were referenced but absent from this ZIP; placeholders were added. Re-export with files and subpages to include them.`:'';alert(`Imported ${htmlFiles.length} Notion page(s) and ${csvFiles.length} CSV table(s). Layout columns, links, toggles, and source highlight colors were kept.${missingText}`)}catch(error){console.error(error);alert('Could not read this file. Export the Notion page as HTML with subpages and files, then select the resulting ZIP.')}}
